INSERT INTO `graph_nodes` VALUES (1,'2026-01-03 02:17:55.415967',4,'{\"content\":\"\",\"type\":\"DIALOGUE\"}','dialogue_1767406664268','dialogue',415,72,NULL,'2026-01-03 02:17:55.415971'),(2,'2026-01-03 02:17:55.422425',4,'{}','start_1767406667533','start',206,186,NULL,'2026-01-03 02:17:55.422427'),(11,'2026-01-03 12:19:03.000000',6,'{}','start_1','start',100,100,NULL,'2026-01-03 12:19:03.000000'),(12,'2026-01-03 12:19:03.000000',6,'{\"content\": \"欢迎来到心域！这是一个对话节点示例。\", \"dialogueType\": \"DIALOGUE\"}','dialogue_1','dialogue',300,100,NULL,'2026-01-03 12:19:03.000000'),(13,'2026-01-03 12:19:03.000000',6,'{\"prompt\": \"请选择你的行动：\", \"options\": [{\"text\": \"选项A：继续前进\", \"effects\": [], \"nextNodeId\": \"condition_1\"}, {\"text\": \"选项B：返回\", \"effects\": [], \"nextNodeId\": \"skill_check_1\"}]}','choice_1','choice',500,100,NULL,'2026-01-03 12:19:03.000000'),(14,'2026-01-03 12:19:03.000000',6,'{\"value\": 10, \"operator\": \"GREATER_THAN\", \"variableName\": \"playerLevel\", \"conditionType\": \"VARIABLE\"}','condition_1','condition',700,100,NULL,'2026-01-03 12:19:03.000000'),(15,'2026-01-03 12:19:03.000000',6,'{\"skillId\": \"strength\", \"minValue\": 50, \"checkType\": \"GREATER_THAN_OR_EQUAL\"}','skill_check_1','skill_check',900,100,NULL,'2026-01-03 12:19:03.000000'),(16,'2026-01-03 12:19:03.000000',6,'{\"changes\": [{\"type\": \"SKILL\", \"value\": 5, \"skillId\": \"strength\", \"operation\": \"ADD\"}, {\"type\": \"VARIABLE\", \"value\": 15, \"operation\": \"SET\", \"variableName\": \"playerLevel\"}]}','state_change_1','state_change',1100,100,NULL,'2026-01-03 12:19:03.000000'),(17,'2026-01-03 12:19:03.000000',6,'{\"timeout\": 30000, \"waitType\": \"USER_INPUT\", \"nextNodeId\": \"end_1\", \"waitCondition\": \"input_received\"}','wait_1','wait',300,300,NULL,'2026-01-03 12:19:03.000000'),(18,'2026-01-03 12:19:03.000000',6,'{\"result\": \"流程结束\", \"endType\": \"NORMAL\"}','end_1','end',500,300,NULL,'2026-01-03 12:19:03.000000'),(28,NULL,10,'{\"name\": \"开始任务\", \"description\": \"冒险者任务开始\"}','start_1','start',100,50,1,NULL),(29,NULL,10,'{\"content\": \"你好，冒险者！有一个危险的任务需要你去完成。\", \"speaker\": \"NPC-村长\", \"description\": \"NPC向玩家介绍任务\"}','dialogue_1','dialogue',100,200,2,NULL),(30,NULL,10,'{\"prompt\": \"你选择如何回应？\", \"options\": [{\"id\": \"accept\", \"text\": \"接受任务\", \"effects\": {\"reputation\": 10}}, {\"id\": \"decline\", \"text\": \"拒绝任务\", \"effects\": {\"reputation\": -5}}, {\"id\": \"ask_more\", \"text\": \"询问更多信息\", \"effects\": {}}], \"description\": \"玩家选择是否接受任务\"}','choice_1','choice',100,350,3,NULL),(31,NULL,10,'{\"condition\": \"userChoice == \"accept\"\", \"description\": \"判断玩家是否接受任务\"}','condition_1','condition',100,500,4,NULL),(32,NULL,10,'{\"content\": \"太好了！这个任务需要你进入森林深处，找到神秘的宝藏。\", \"speaker\": \"NPC-村长\", \"description\": \"任务详情\"}','dialogue_2','dialogue',100,650,5,NULL),(33,NULL,10,'{\"skill\": \"exploration\", \"difficulty\": 15, \"successEffects\": {\"experience\": 50}, \"failureEffects\": {\"health\": -10}, \"description\": \"探索技能检查\"}','skill_check_1','skill_check',100,800,6,NULL),(34,NULL,10,'{\"changes\": {\"items\": [{\"id\": \"map\", \"name\": \"藏宝图\", \"count\": 1}], \"variables\": {\"inForest\": true}}, \"description\": \"获得藏宝图\"}','state_change_1','state_change',100,950,7,NULL),(35,NULL,10,'{\"waitType\": \"USER_INPUT\", \"waitCondition\": \"playerReady\", \"timeout\": 30000, \"description\": \"等待玩家准备\"}','wait_1','wait',100,1100,8,NULL),(36,NULL,10,'{\"content\": \"好吧，如果你改变主意，随时可以来找我。\", \"speaker\": \"NPC-村长\", \"description\": \"玩家拒绝任务\"}','dialogue_3','dialogue',300,650,9,NULL),(37,NULL,10,'{\"content\": \"任务很危险，但奖励丰厚。你需要探索森林，打败怪物，找到宝藏。\", \"speaker\": \"NPC-村长\", \"description\": \"提供更多信息\"}','dialogue_4','dialogue',300,350,10,NULL),(38,NULL,10,'{\"condition\": \"skillCheckResult == true\", \"description\": \"判断技能检查是否成功\"}','condition_2','condition',100,1250,11,NULL),(39,NULL,10,'{\"content\": \"你成功找到了宝藏的位置！\", \"speaker\": \"系统\", \"description\": \"探索成功\"}','dialogue_5','dialogue',50,140