  `message_category` enum('ESOUL_LETTER','RESONANCE','SYSTEM','USER_MESSAGE') NOT NULL,
  `message_type` enum('ESOUL_GREETING','ESOUL_CARE','ESOUL_SHARE','ESOUL_REMINDER','RESONANCE_LIKE','RESONANCE_COMMENT','RESONANCE_MESSAGE','RESONANCE_SHARE','RESONANCE_CONNECTION_REQUEST','SYSTEM_NOTIFICATION','SYSTEM_FEEDBACK','SYSTEM_DIALOGUE','USER_PRIVATE_MESSAGE','USER_REPLY','USER_INTERACTION') NOT NULL,
