--
-- Table structure for table `mailbox_notification_settings`
--

DROP TABLE IF EXISTS `mailbox_notification_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mailbox_notification_settings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `enable_notifications` bit(1) NOT NULL,
  `esoul_letter_enabled` bit(1) NOT NULL,
