CREATE TABLE `scenario_items` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) DEFAULT NULL,
  `description` text,
  `icon_url` varchar(500) DEFAULT NULL,
  `is_active` bit(1) NOT NULL,
  `is_deleted` bit(1) NOT NULL,
  `item_id` varchar(100) NOT NULL,
  `item_type` varchar(50) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `sort_order` int DEFAULT NULL,
  `tags` varchar(200) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `system_era_id` bigint DEFAULT NULL COMMENT '关联的系统预设时代ID',
  `user_id` bigint DEFAULT NULL,
  `era_id` bigint DEFAULT NULL,
  `is_system` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_2yaf5jmx0snwflqtrxuepdkux` (`item_id`),
  KEY `idx_system_era_id` (`system_era_id`)
) ENGINE=InnoDB AUTO_INCREMENT=337 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
