INSERT INTO `skill_definitions` VALUES (10,'HeartSphere CBT Team','认知,思维,想法,负面,重构,扭曲,自动思维,认知重构,CBT,认知行为',NULL,'PSYCHIATRY','2026-01-05 07:52:45.000000','认知行为疗法核心技能 - 帮助识别、评估和重构负面思维模式，包括自动思维识别、认知扭曲检测、证据评估和思维重构','{\n        \"rule\": \"cognitive_restructuring\",\n        \"workflow\": {\n            \"identify\": {\n                \"steps\": [\"识别情境\", \"提取自动思维\", \"识别情绪\", \"评估强度\"]\n            },\n            \"evaluate\": {\n                \"steps\": [\"收集支持证据\", \"收集反驳证据\", \"识别认知扭曲\", \"评估思维合理性\"]\n            },\n            \"restructure\": {\n                \"steps\": [\"生成替代思维\", \"评估替代思维\", \"制定行动计划\", \"记录结果\"]\n            },\n            \"challenge\": {\n                \"steps\": [\"识别扭曲类型\", \"挑战扭曲逻辑\", \"寻找替代解释\", \"验证新思维\"]\n            }\n        }\n    }','RULE_BASED','{\n        \"type\": \"object\",\n        \"properties\": {\n            \"action\": {\n                \"type\": \"string\",\n                \"enum\": [\"identify\", \"evaluate\", \"restructure\", \"challenge\"],\n                \"description\": \"操作类型: identify(识别自动思维), evaluate(评估思维证据), restructure(重构思维), challenge(挑战认知扭曲)\"\n            },\n            \"patientId\": {\n                \"type\": \"string\",\n                \"description\": \"患者ID\"\n            },\n            \"situation\": {\n                \"type\": \"string\",\n                \"description\": \"触发情境描述\"\n            },\n            \"automaticThought\": {\n                \"type\": \"string\",\n                \"description\": \"自动思维内容\"\n            },\n            \"emotion\": {\n                \"type\": \"string\",\n                \"description\": \"伴随情绪（如：焦虑、抑郁、愤怒）\"\n            },\n            \"intensity\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"maximum\": 10,\n                \"description\": \"情绪强度 (0-10)\"\n            },\n            \"cognitiveDistortion\": {\n                \"type\": \"string\",\n                \"enum\": [\"全或无思维\", \"过度概括\", \"心理过滤\", \"贬低积极\", \"读心术\", \"灾难化\", \"情绪推理\", \"应该陈述\", \"贴标签\", \"个人化\"],\n                \"description\": \"认知扭曲类型\"\n            },\n            \"evidenceFor\": {\n                \"type\": \"array\",\n                \"items\": {\"type\": \"string\"},\n                \"description\": \"支持该思维的证据列表\"\n            },\n            \"evidenceAgainst\": {\n                \"type\": \"array\",\n                \"items\": {\"type\": \"string\"},\n                \"description\": \"反驳该思维的证据列表\"\n            },\n            \"alternativeThought\": {\n                \"type\": \"string\",\n                \"description\": \"替代性思维\"\n            }\n        },\n        \"required\": [\"action\"]\n    }',NULL,_binary '',NULL,-1,'CBT认知重构','PSYCHIATRY_ACCESS','cbt-cognitive-restructuring','ACTIVE','2026-01-06 13:31:05.000000','1.0.0'),(11,'HeartSphere CBT Team','行为,活动,激活,抑郁,情绪,计划,执行,监控,评估,行为激活,BA,CBT',NULL,'PSYCHIATRY','2026-01-05 07:52:47.000000','认知行为疗法核心技能 - 通过增加积极活动来改善情绪，包括活动监控、活动计划、活动执行和效果评估','{\n        \"rule\": \"behavioral_activation\",\n        \"workflow\": {\n            \"monitor\": {\n                \"steps\": [\"记录活动\", \"评估愉悦度\", \"评估掌控感\", \"分析模式\"]\n            },\n            \"plan\": {\n                \"steps\": [\"选择活动\", \"设置时间\", \"评估难度\", \"识别障碍\", \"制定应对策略\"]\n            },\n            \"execute\": {\n                \"steps\": [\"执行活动\", \"记录实际体验\", \"评估完成度\", \"记录困难\"]\n            },\n            \"evaluate\": {\n                \"steps\": [\"比较计划与实际\", \"评估效果\", \"识别成功因素\", \"调整计划\"]\n            }\n        }\n    }','RULE_BASED','{\n        \"type\": \"object\",\n        \"properties\": {\n            \"action\": {\n                \"type\": \"string\",\n                \"enum\": [\"monitor\", \"plan\", \"execute\", \"evaluate\"],\n                \"description\": \"操作类型: monitor(监控活动), plan(制定活动计划), execute(执行活动), evaluate(评估效果)\"\n            },\n            \"patientId\": {\n                \"type\": \"string\",\n                \"description\": \"患者ID\"\n            },\n            \"date\": {\n                \"type\": \"string\",\n                \"format\": \"date\",\n                \"description\": \"日期 (YYYY-MM-DD)\"\n            },\n            \"activities\": {\n                \"type\": \"array\",\n                \"items\": {\n                    \"type\": \"object\",\n                    \"properties\": {\n                        \"activity\": {\"type\": \"string\", \"description\": \"活动名称\"},\n                        \"time\": {\"type\": \"string\", \"description\": \"时间\"},\n                        \"pleasure\": {\"type\": \"integer\", \"minimum\": 0, \"maximum\": 10, \"description\": \"愉悦度 (0-10)\"},\n                        \"mastery\": {\"type\": \"integer\", \"minimum\": 0, \"maximum\": 10, \"description\": \"掌控感 (0-10)\"},\n                        \"duration\": {\"type\": \"integer\", \"description\": \"持续时间（分钟）\"}\n                    }\n                },\n                \"description\": \"活动列表\"\n            },\n            \"activityPlan\": {\n                \"type\": \"object\",\n                \"properties\": {\n                    \"activity\": {\"type\": \"string\", \"description\": \"活动名称\"},\n                    \"scheduledTime\": {\"type\": \"string\", \"description\": \"计划时间\"},\n                    \"difficulty\": {\"type\": \"string\", \"enum\": [\"easy\", \"medium\", \"hard\"], \"description\": \"难度等级\"},\n                    \"expectedPleasure\": {\"type\": \"integer\", \"minimum\": 0, \"maximum\": 10, \"description\": \"预期愉悦度\"},\n                    \"barriers\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"潜在障碍\"}\n                },\n                \"description\": \"活动计划\"\n            },\n            \"activityCategory\": {\n                \"type\": \"string\",\n                \"enum\": [\"exercise\", \"social\", \"hobby\", \"work\", \"self-care\", \"learning\", \"creative\", \"relaxation\"],\n                \"description\": \"活动类别：运动、社交、爱好、工作、自我照顾、学习、创造性、放松\"\n            },\n            \"completed\": {\n                \"type\": \"boolean\",\n                \"description\": \"是否完成\"\n            },\n            \"actualPleasure\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"maximum\": 10,\n                \"description\": \"实际愉悦度 (0-10)\"\n            },\n            \"actualMastery\": {\n                \"type\": \"integer\",\n                \"minimum\": 0,\n                \"maximum\": 10,\n                \"description\": \"实际掌控感 (0-10)\"\n            }\n        },\n        \"required\": [\"action\"]\n    }',NULL,_binary '',NULL,-1,'CBT行为激活','PSYCHIATRY_ACCESS','cbt-behavioral-activation','ACTIVE','2026-01-06 13:31:05.000000','1.0.0'),(14,'HeartSphere Test','æµ‹è¯•,test,echo',NULL,'UTILITY','2026-01-06 13:31:05.000000','这是一个简单的测试技能，用于验证技能系统的基本功能。可以接收用户输入并返回处理结果。','{\n        \"type\": \"RULE_BASED\",\n        \"description\": \"基于规则的简单处理\"\n    }','RULE_BASED','{\n        \"type\": \"object\",\n        \"properties\": {\n            \"input\": {\n                \"type\": \"string\",\n                \"description\": \"用户输入的内容\"\n            },\n            \"action\": {\n                \"type\": \"string\",\n                \"enum\": [\"echo\", \"uppercase\", \"lowercase\", \"reverse\"],\n                \"description\": \"处理动作: echo(原样返回), uppercase(转大写), lowercase(转小写), reverse(反转)\"\n            }\n        },\n        \"required\": [\"input\"]\n    }',NULL,_binary '\0',NULL,-1,'测试技能',NULL,'test-skill','ACTIVE','2026-01-06 13:31:05.000000','1.0.0');
