INSERT INTO `skill_resources` VALUES (8,'2026-01-05 07:52:45.000000','{\"situation\": \"\", \"automaticThought\": \"\", \"emotion\": \"\", \"intensity\": 0, \"cognitiveDistortion\": \"\", \"evidenceFor\": [], \"evidenceAgainst\": [], \"alternativeThought\": \"\", \"newEmotion\": \"\", \"newIntensity\": 0}','思维记录表',1,'TEMPLATE','/skills/cbt/cognitive-restructuring/thought-record-template.json','cbt-cognitive-restructuring'),(9,'2026-01-05 07:52:45.000000','{\"全或无思维\": \"如果我不完美，我就是个失败者\", \"过度概括\": \"一次失败意味着我永远会失败\", \"心理过滤\": \"只关注负面，忽略积极\", \"贬低积极\": \"那只是运气好\", \"读心术\": \"他们一定觉得我很蠢\", \"灾难化\": \"如果这次考试失败，我的人生就完了\", \"情绪推理\": \"我感觉很糟糕，所以情况一定很糟糕\", \"应该陈述\": \"我应该总是做得最好\", \"贴标签\": \"我是个失败者\", \"个人化\": \"都是我的错\"}','认知扭曲示例',2,'EXAMPLE','/skills/cbt/cognitive-restructuring/distortion-examples.json','cbt-cognitive-restructuring'),(10,'2026-01-05 07:52:45.000000','[\"这个想法的证据是什么？\", \"有没有其他可能的解释？\", \"最坏的情况是什么？我能应对吗？\", \"最好的情况是什么？\", \"最现实的情况是什么？\", \"这个想法对我有什么影响？\", \"如果朋友有同样的想法，我会对他说什么？\", \"我应该做什么？\"]','苏格拉底式提问清单',3,'CONFIG','/skills/cbt/cognitive-restructuring/socratic-questions.json','cbt-cognitive-restructuring'),(11,'2026-01-05 07:52:47.000000','{\"date\": \"\", \"activities\": [{\"activity\": \"\", \"time\": \"\", \"pleasure\": 0, \"mastery\": 0, \"duration\": 0}]}','活动监控表',1,'TEMPLATE','/skills/cbt/behavioral-activation/activity-monitoring-template.json','cbt-behavioral-activation'),(12,'2026-01-05 07:52:47.000000','{\"activity\": \"\", \"scheduledTime\": \"\", \"difficulty\": \"medium\", \"expectedPleasure\": 5, \"barriers\": [], \"copingStrategies\": [], \"activityCategory\": \"\"}','活动计划表',2,'TEMPLATE','/skills/cbt/behavioral-activation/activity-planning-template.json','cbt-behavioral-activation'),(13,'2026-01-05 07:52:47.000000','{\"exercise\": [\"散步\", \"跑步\", \"瑜伽\", \"游泳\", \"骑自行车\"], \"social\": [\"与朋友见面\", \"打电话\", \"参加聚会\", \"志愿服务\"], \"hobby\": [\"阅读\", \"听音乐\", \"看电影\", \"烹饪\", \"园艺\"], \"work\": [\"完成工作任务\", \"学习新技能\", \"整理文件\"], \"self-care\": [\"洗