  `theme_color` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_accent` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `first_message` text COLLATE utf8mb4_unicode_ci,
  `system_instruction` text COLLATE utf8mb4_unicode_ci,
  `voice_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mbti` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
