  `secrets` text COLLATE utf8mb4_unicode_ci,
  `motivations` text COLLATE utf8mb4_unicode_ci,
  `relationships` text COLLATE utf8mb4_unicode_ci,
  `system_era_id` bigint DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
