INSERT INTO `system_eras` VALUES (23,'我的大学','大学时代，青春校园生活',2018,2022,'http://localhost:8081/images/general/2025/12/6519d605-51cc-4f4b-8c94-4eee12d3908a.png',1,1,'2025-12-15 15:56:25','2026-01-04 07:14:32'),(24,'我的中学','中学时代，青涩年华',2015,2018,'general/2025/12/615e567f-20d8-4374-951f-b575aba689cb.png',1,2,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(25,'我的工作','职场时代，工作环境',2022,NULL,'general/2025/12/d8f0635e-3711-4283-aba5-76c2f76df8c9.png',1,3,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(26,'我的童年','童年时代，纯真回忆',2005,2015,'general/2025/12/22b64f01-4216-45d5-a76e-7e039d7f6745.png',1,4,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(27,'我的故乡','故乡时代，家乡记忆',NULL,NULL,'general/2025/12/7d15aa23-e7ff-42c3-ad52-c0caffc05b8f.png',1,5,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(28,'三国时代','三国争霸时代，英雄辈出',220,280,'general/2025/12/5d9703ae-8a7d-41e5-9d9b-d312364edfc9.png',1,10,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(29,'秦王朝','大秦帝国，统一六国',221,207,'general/2025/12/096dd94f-304e-4657-9ac4-1b428d5a464c.png',1,11,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(30,'唐朝盛世','大唐盛世，文化繁荣',618,907,'general/2025/12/50ee7222-2d6c-4a1f-8650-9ab1ce4a6e9c.png',1,12,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(31,'宋朝文雅','宋朝文雅时代，诗词盛行',960,1279,'general/2025/12/1d9f9d17-fb20-4def-9870-3267b242987c.png',1,13,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(32,'明朝江湖','明朝江湖时代，武侠世界',1368,1644,'general/2025/12/9c649ef7-42c0-416c-87cb-fe8d3f1ce571.png',1,14,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(33,'未来世界','未来世界，科技发达',2100,NULL,'general/2025/12/7ba38861-59b1-41e9-9b15-b0265ebf611b.png',1,20,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(35,'废土世界','废土世界，末日之后',2050,NULL,'general/2025/12/b331c235-292e-43bd-8e8f-7a15e52a2731.png',1,22,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(36,'魔法世界','魔法世界，奇幻大陆',NULL,NULL,'general/2025/12/ae4aa7de-8422-4993-ab82-5d8d2ca14b6f.png',1,30,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(37,'童话世界','童话世界，梦幻王国',NULL,NULL,'general/2025/12/3870b2e4-0983-42c9-add3-d30612d7d778.png',1,31,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(38,'蒸汽朋克','蒸汽朋克时代，机械美学',1850,1900,'general/2025/12/ed2cc44a-c3a0-400f-9b83-195181b019ad.png',1,32,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(39,'古代埃及','古埃及时代，法老王朝',-3100,-30,'general/2025/12/4ad8b8f9-208a-48a1-8cc6-07d39272453b.png',1,40,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(40,'古希腊','古希腊时代，神话传说',-800,-146,'general/2025/12/567a1560-ab53-410a-ba27-fa953db338e2.png',1,41,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(41,'中世纪欧洲','中世纪欧洲，骑士时代',476,1453,'general/2025/12/ea169199-57e0-4b86-a6f6-7b5bc17b98c6.png',1,42,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(42,'文艺复兴','文艺复兴时代，艺术繁荣',1400,1600,'general/2025/12/36fac7d9-7ccf-4c97-88da-058a59f7a9ca.png',1,43,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(43,'工业革命','工业革命时代，机器轰鸣',1760,1840,'general/2025/12/fc6662c2-6fa5-4766-a31f-02055f3e19b7.png',1,44,'2025-12-15 15:56:25','2026-01-03 13:43:54'),(44,'心理治疗诊所','心理治疗诊所，专业安全保密的心理治疗空间',NULL,NULL,'general/2025/12/d4c0a40c-9d60-4c10-9c4b-b156b14124e3.png',1,6,'2025-12-16 11:49:04','2026-01-03 13:43:54'),(45,'我的家庭','一个温馨的家庭场景，包含家庭成员之间的日常互动和情感交流。',NULL,NULL,'https://picsum.photos/seed/family_home/1080/1920',1,100,'2025-12-18 01:02:12','2025-12-18 01:02:12'),(49,'test','test',NULL,NULL,'http://localhost:8081/images/general/2025/12/0948a32a-7c40-424f-b660-b3f8a2fa9eaf.png',1,0,'2026-01-03 11:19:57','2026-01-03 11:19:57'),(50,'日常生活助手','【生活助手型角色】提供日常生活帮助的专业数字人角色，包括时间管理、健康生活、学习成长、心理健康、情感陪伴等领域。这些角色专注于解决实际生活问题，提供专业指导和情感陪伴。',NULL,NULL,'placeholder://era/daily_life_assistant.jpg',1,100,'2026-01-06 17:12:17','2026-01-06 17:12:17');
