DROP TABLE IF EXISTS `system_main_stories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_main_stories` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `age` int DEFAULT NULL,
  `avatar_url` text,
  `background_url` text,
  `bio` text,
  `catchphrases` text,
  `color_accent` varchar(20) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `first_message` text,
  `is_active` bit(1) NOT NULL,
  `motivations` text,
  `name` varchar(200) NOT NULL,
  `role` varchar(50) DEFAULT NULL,
  `secrets` text,
  `sort_order` int DEFAULT NULL,
  `speech_style` text,
  `system_instruction` text,
  `tags` text,
  `theme_color` varchar(50) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `voice_name` varchar(50) DEFAULT NULL,
  `system_era_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `FK1btx954cdiqkbpahxsvow8ya0` (`system_era_id`),
  CONSTRAINT `FK1btx954cdiqkbpahxsvow8ya0` FOREIGN KEY (`system_era_id`) REFERENCES `system_eras` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
