--
-- Table structure for table `system_scripts`
--

DROP TABLE IF EXISTS `system_scripts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_scripts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '剧本标题',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '剧本描述',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '剧本内容（JSON格式）',
  `scene_count` int NOT NULL DEFAULT '1' COMMENT '场景数量',
  `system_era_id` bigint DEFAULT NULL COMMENT '关联的系统时代ID',
  `character_ids` text COLLATE utf8mb4_unicode_ci COMMENT '关联的角色ID列表（JSON数组）',
