INSERT INTO `system_scripts` VALUES (72,'我的大学 - 初遇篇','在我的大学中与大学室友、温柔学妹、大学学长的精彩故事，包含15个互动节点。','{\"startNodeId\":\"start\",\"nodes\":{\"start\":{\"id\":\"start\",\"title\":\"开始\",\"text\":\"欢迎来到我的大学！你在这里遇到了大学室友、温柔学妹、大学学长。\",\"backgroundHint\":\"我的大学的场景\"},\"node_1\":{\"id\":\"node_1\",\"title\":\"初次相遇\",\"text\":\"在大学室友中，你发现了许多有趣的事物和秘密。\",\"backgroundHint\":\"我的大学的初次相遇场景\",\"options\":[{\"text\":\"继续探索\",\"nextNodeId\":\"node_2\"},{\"text\":\"选择另一条路\",\"nextNodeId\":\"node_5\"}]},\"node_2\":{\"id\":\"node_2\",\"title\":\"深入对话\",\"text\":\"在大学室友中，你发现了许多有趣的事物和秘密。\",\"backgroundHint\":\"我的大学的深入对话场景\",\"options\":[{\"text\":\"继续探索\",\"nextNodeId\":\"node_3\"}]},\"node_3\":{\"id\":\"node_3\",\"title\":\"探索发现\",\"text\":\"你与大学学长一起解决了问题，共同成长和进步。\",\"backgroundHint\":\"我的大学的探索发现场景\",\"options\":[{\"text\":\"继续探索\",\"nextNodeId\":\"node_4\"},{\"text\":\"选择另一条路\",\"nextNodeId\":\"node_6\"}]},\"node_4\":{\"id\":\"node_4\",\"title\":\"情感交流\",\"text\":\"在大学学长中，你发现了许多有趣的事物和秘密。\",\"backgroundHint\":\"我的大学的情感交流场景\",\"options\":[{\"text\":\"继续探索\",\"nextNodeId\":\"node_5\"}]},\"node_5\":{\"id\":\"node_5\",\"title\":\"共同冒险\",\"text\":\"在大学学长的陪伴下，你体验了我的大学的独特魅力。\",\"backgroundHint\":\"我的大学的共同冒险场景\",\"options\":[{\"text\":\"继续探索\",\"nextNodeId\":\"node_6\"},{\"text\":\"选择另一条路\",\"nextNodeId\":\"node_8\"}]},\"node_6\":{\"id\":\"node_6\",\"title\":\"面临挑战\",\"text\":\"你与大学学长展开了深入的对话，了解了更多关于他们的信息。\",\"backgroundHint\":\"我的大学的面临挑战场景\",\"options\":[{\"text\":\"继续探索\",\"nextNodeId\":\"node_7\"}]},\"node_7\":{\"id\":\"node_7\",\"title\":\"解决问题\",\"text\":\"在温柔学妹的帮助下，你克服了困难，获得了新的体验。\",\"backgroundHint\":\"我的大学的解决问题场景\",\"options\":[{\"text\":\"继续探索\",\"nextNodeId\":\"node_8\"},{\"text\":\"选择另一条路\",\"nextNodeId\":\"node_10\"}]},\"node_8\":{\"id\":\"node_8\",\"title\":\"建立信任\",\"text\":\"在大学学长的陪伴下，你体验了我的大学的独特魅力。\",\"backgroundHint\":\"我的大学的建立信任场景\",\"options\":[{\"text\":\"继续探索\",\"nextNodeId\":\"node_9\"},{\"text\":\"选择另一条路\",\"nextNodeId\":\"node_12\"},{\"text\":\"结束故事\",\"nextNodeId\":\"end\"}]},